def append_engine_ini_config(config, engine_ini_config):
    config.SP_CORE.OVERRIDE_CONFIG_ENGINE_INI = True
    existing_engine_ini_config = config.SP_CORE.CONFIG_ENGINE_INI_STRING or ""
