def build_config(
        args,
        orbit_spec=None,
        benchmarking=False,
        max_num_frames=None,
        width=None,
        height=None,
        user_config_files=None):
    if user_config_files is None:
        user_config_files = [os.path.realpath(os.path.join(os.path.dirname(__file__), "user_config.yaml"))]
    config = spear.get_config(user_config_files=user_config_files)
